    { q: "Ofisda qanday mish-mish bor?", options: ["Qayta tashkil etish bo‘larkan", "Ofis boshqa joyga ko‘charkan", "Yangi direktor kelarkan"], answer: 0, line: 0 },
    { q: "Qaysi bo‘limlar birlashtiriladi?", options: ["Logistika va buxgalteriya", "Dilshodning bo‘limi va sotuv bo‘limi", "Kadrlar va sotuv bo‘limi"], answer: 1, line: 4 },
    { q: "Dilshodni ko‘proq nima tashvishlantiryapti?", options: ["Shartnomasi tugashi", "Choraklik mukofot bekor qilinishi", "Yangi ish vaqti"], answer: 1, line: 8 },
    { q: "Dilshod mukofot puliga nima qilmoqchi edi?", options: ["Mashina olmoqchi edi", "Onasiga operatsiya uchun jo‘natmoqchi edi", "Kvartira ijarasini to‘lamoqchi edi"], answer: 1, line: 10 },
    { q: "Svetlana nima maslahat beradi?", options: ["Ertalab Igor Petrovich bilan gaplashishni", "Darhol boshqa ish izlashni", "Direktorga shikoyat yozishni"], answer: 0, line: 17 }
